package com.estateflow.service;
import com.estateflow.dao.*;import com.estateflow.exception.*;import com.estateflow.model.*;import com.estateflow.support.TestAuth;import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;
class VendorServiceTest{
 @Test void trimsAndSavesVendor(){VendorDao dao=mock(VendorDao.class);when(dao.isAvailable()).thenReturn(true);when(dao.insert(any())).thenAnswer(i->{Vendor v=i.getArgument(0);return new Vendor(7L,v.name(),v.category(),v.phone(),v.email(),v.address(),v.notes(),v.active());});VendorService service=new VendorService(dao,new PassThroughTransactionManager(),AuditService.noop(),TestAuth.admin());Vendor result=assertDoesNotThrow(()->service.save(new Vendor(null,"  North Plumbing ",VendorCategory.PLUMBING," 555 ",null,null,null,true)));assertEquals(7L,result.id());assertEquals("North Plumbing",result.name());assertEquals("555",result.phone());}
 @Test void requiresNameAndCategory(){VendorDao dao=mock(VendorDao.class);when(dao.isAvailable()).thenReturn(true);VendorService service=new VendorService(dao,new PassThroughTransactionManager(),AuditService.noop(),TestAuth.admin());assertThrows(ValidationException.class,()->service.save(new Vendor(null," ",VendorCategory.OTHER,null,null,null,null,true)));assertThrows(ValidationException.class,()->service.save(new Vendor(null,"Vendor",null,null,null,null,null,true)));verify(dao,never()).insert(any());}
}
